/**
 * Render `docs/reference/api.md` from the API's OpenAPI document
 * (`packages/api-client/openapi.json`, regenerated by `pnpm --filter @graphgoblin/api-client generate`).
 * Pure: takes the parsed document, returns Markdown.
 */

const METHODS = ['get', 'post', 'put', 'patch', 'delete'];

function cell(text) {
  return String(text).replace(/\|/g, '\\|').replace(/\n/g, ' ');
}

function refName(ref) {
  return ref.slice(ref.lastIndexOf('/') + 1);
}

/** A short name for a request body schema: the component name, or its top-level fields. */
export function schemaName(schema) {
  if (!schema || typeof schema !== 'object') return '-';
  if (schema.$ref) return `\`${refName(schema.$ref)}\``;
  if (schema.type === 'array') return `array of ${schemaName(schema.items)}`;
  const props = Object.keys(schema.properties ?? {});
  if (props.length > 0) {
    const required = new Set(schema.required ?? []);
    return `\`{ ${props.map((p) => (required.has(p) ? p : `${p}?`)).join(', ')} }\``;
  }
  return schema.type ? `\`${schema.type}\`` : 'any';
}

/** Operations grouped by their first tag, in the document's tag order. */
export function operationsByTag(document) {
  const order = (document.tags ?? []).map((t) => t.name);
  const groups = new Map(order.map((name) => [name, []]));
  for (const [path, item] of Object.entries(document.paths ?? {})) {
    for (const method of METHODS) {
      const op = item[method];
      if (!op) continue;
      const tag = op.tags?.[0] ?? 'other';
      if (!groups.has(tag)) groups.set(tag, []);
      groups.get(tag).push({ method, path, op });
    }
  }
  return groups;
}

/** Operations without a summary. The generator fails on any, so every route documents itself. */
export function operationsWithoutSummary(document) {
  const missing = [];
  for (const ops of operationsByTag(document).values()) {
    for (const { method, path, op } of ops) {
      if (!op.summary) missing.push(`${method.toUpperCase()} ${path}`);
    }
  }
  return missing;
}

function parameters(op) {
  return (op.parameters ?? []).map((p) => {
    const type = p.schema?.type ? `: ${p.schema.type}` : '';
    return `\`${p.name}\`${type} (${p.in}${p.required ? ', required' : ''})`;
  });
}

function requestBody(op) {
  const content = op.requestBody?.content;
  if (!content) return undefined;
  const [type, media] = Object.entries(content)[0] ?? [];
  if (!type) return undefined;
  const name = schemaName(media?.schema);
  return type === 'application/json' ? name : `${name} as \`${type}\``;
}

function responses(op) {
  return Object.keys(op.responses ?? {}).join(', ');
}

export function renderApiReference(document) {
  const missing = operationsWithoutSummary(document);
  if (missing.length > 0) {
    throw new Error(
      `API reference: add a schema summary to ${missing.join(', ')} (apps/api/src/routes)`,
    );
  }
  const tags = new Map((document.tags ?? []).map((t) => [t.name, t.description ?? '']));
  const out = [
    '# API reference',
    '',
    '<!-- Generated by `pnpm docs:generate` from `packages/api-client/openapi.json`. Do not edit by hand; `pnpm check:docs` fails when this file is stale. -->',
    '',
    `${document.info?.title ?? 'API'} ${document.info?.version ?? ''}. Concepts, SSE, authentication, and error shapes are in [07 - API, streaming, and MCP](../07-api-and-streaming.md); the machine-readable document is served at \`GET /openapi.json\`. Every route needs a bearer API key when keys are required, except \`/healthz\`, \`/version\`, \`/openapi.json\`, \`/docs\`, and \`/hooks/*\`. Errors are RFC 9457 Problem Details with a stable \`code\`.`,
    '',
  ];
  for (const [tag, ops] of operationsByTag(document)) {
    if (ops.length === 0) continue;
    out.push(`## ${tag}`, '');
    if (tags.get(tag)) out.push(`${tags.get(tag)}.`, '');
    out.push('| Method | Path | Summary | Parameters | Request body | Responses |');
    out.push('| --- | --- | --- | --- | --- | --- |');
    for (const { method, path, op } of ops) {
      out.push(
        `| ${method.toUpperCase()} | \`${path}\` | ${cell(op.summary)} | ${cell(parameters(op).join(', ') || '-')} | ${cell(requestBody(op) ?? '-')} | ${responses(op)} |`,
      );
    }
    out.push('');
  }
  return out.join('\n');
}
